/*
 * Port of shared/src/commonMain/kotlin/net/newpipe/app/model/AboutLibraries.kt - the root of
 * the BOM generated by the AboutLibraries Gradle plugin, read by the About / Licences screen.
 *
 * kotlinx.serialization (`ignoreUnknownKeys = true`, `coerceInputValues = true` in
 * SerializationModule.provideJson) becomes JSON.parse plus the defensive per-field defaults
 * below, which is the same tolerance.
 */

import { Library, RawLibrary } from './Library';

/** Raw JSON shape of the BOM root. */
interface RawAboutLibraries {
  libraries?: RawLibrary[];
}

export class AboutLibraries {
  libraries: Library[] = [];

  static fromRaw(raw: RawAboutLibraries): AboutLibraries {
    const out: AboutLibraries = new AboutLibraries();
    const rawLibraries: RawLibrary[] = raw.libraries === undefined ? [] : raw.libraries;
    const libraries: Library[] = [];
    for (const rawLibrary of rawLibraries) {
      libraries.push(Library.fromRaw(rawLibrary));
    }
    out.libraries = libraries;
    return out;
  }

  /** Parses the bundled `aboutlibraries.json` rawfile content. */
  static parse(json: string): AboutLibraries {
    return AboutLibraries.fromRaw(JSON.parse(json) as RawAboutLibraries);
  }
}
